use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-blocked-load176";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!Path::new(&format!("{R}/review.json")).exists());let p=read(format!("{R}/native-plan.json"));let mut normalized=p.clone();normalized.as_object_mut().unwrap().entry("environment").or_insert(json!({}));for s in normalized["steps"].as_array_mut().unwrap(){s.as_object_mut().unwrap().entry("environment").or_insert(json!({}));s.as_object_mut().unwrap().entry("required_tests").or_insert(json!([]));s.as_object_mut().unwrap().entry("unfiltered").or_insert(json!(false));}assert_eq!(read(format!("{R}/native/protocol.json")),normalized);let mut pins:BTreeMap<String,String>=serde_json::from_value(read(p["source_pins"].as_str().unwrap())).unwrap();assert_eq!(read(format!("{R}/native/source-pins.json")),json!(pins));assert_eq!(read(format!("{R}/native/result.json"))["status"],"complete");assert_eq!(read(format!("{R}/native/attempt-0.json"))["resume"],false);assert_eq!(fs::read_dir(format!("{R}/native")).unwrap().filter(|e|e.as_ref().unwrap().file_name().to_string_lossy().starts_with("attempt-")).count(),1);let mut names=Vec::new();for s in p["steps"].as_array().unwrap(){let name=s["name"].as_str().unwrap();names.push(name.to_string());let c=read(format!("{R}/native/{name}/command.json"));let e=read(format!("{R}/native/{name}/exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(hash(format!("{R}/native/{name}/{stream}.log")),e[format!("{stream}_sha256")]);}let argv=c["argv"].as_array().unwrap();let declared=s["argv"].as_array().unwrap();assert!(argv.ends_with(declared));assert_eq!(argv.len(),declared.len()+4);assert_eq!(argv[..3],[json!("timeout"),json!("-k"),json!("5s")]);assert_eq!(argv[3],format!("{}s",s["timeout_seconds"].as_u64().unwrap()));let mut env=s["environment"].clone();env.as_object_mut().unwrap().remove("RUSTC");env.as_object_mut().unwrap().remove("RUSTUP_TOOLCHAIN");assert_eq!(c["environment"],env);}assert_eq!(names.len(),3);assert_eq!(read(format!("{R}/native/completed.json")),json!(names));let tests=read(format!("{R}/native/loader-tests/tests.json"));assert_eq!(tests["passed_tests"].as_array().unwrap().len(),2);let stdout=fs::read_to_string(format!("{R}/native/loader-tests/stdout.log")).unwrap();assert!(stdout.contains("2 passed; 0 failed; 0 ignored; 0 measured; 35 filtered out"));
let info=read(format!("{R}/frozen-candidate.json"));assert_eq!(info["rustflags"],fs::read_to_string(format!("{R}/candidate-flags.txt")).unwrap());for(p,h)in info["input_pins"].as_object().unwrap(){pins.insert(p.clone(),h.as_str().unwrap().to_string());}for(p,h)in&pins{assert_eq!(hash(p),*h,"pin{p}");}let m=read(format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"));let audit=read(format!("{R}/source-audit.json"));let suffix=audit["field_lib_suffix"].as_str().unwrap().as_bytes();let mut exact=0;for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new(Z).join(p)),h.as_str().unwrap());let mut b=fs::read(Path::new(R).join("source").join(p)).unwrap();if format!("{:x}",Sha256::digest(&b))==h.as_str().unwrap(){exact+=1;}if p=="crates/zopro-bn254/src/lib.rs"{assert!(b.ends_with(suffix));b.truncate(b.len()-suffix.len());}assert_eq!(format!("{:x}",Sha256::digest(b)),h.as_str().unwrap());}assert_eq!(exact,175);assert_eq!(fs::read(format!("{R}/blocked_input.rs")).unwrap(),fs::read(format!("{R}/source/crates/zopro-bn254/src/blocked_input.rs")).unwrap());let source=fs::read_to_string(format!("{R}/blocked_input.rs")).unwrap();for needle in["indices.iter().all(|i|i/8==b0||i/8==b1)","_mm512_maskz_loadu_epi64","_mm512_i64gather_epi64::<8>","const{assert!(FIELD==0||FIELD==2);}","for _ in 0..8192","let mut tile=[[0u64;16];8]"]{assert!(source.contains(needle));}let ledger="/home/ubuntu/src/zopro-perf-work/finalize-drain-bundle176/proof-sha256-after.json";assert_eq!(read(ledger).as_array().unwrap().len(),29953);assert_eq!(hash(m["native_binary"].as_str().unwrap()),m["native_binary_sha256"]);let out=json!({"review_passed":true,"review_scope":"qualification receipt, source recovery and bounds inspection; not a formal machine-code proof","source_and_library_pins":pins.len(),"successful_commands":3,"focused_native_tests":2,"inherited_field_tests_filtered":35,"production_originals_exact":176,"private_originals_exact":175,"all176recover":true,"existing_field_arithmetic_generated_source_core_prover_exact":true,"qualified_child_exact":true,"same_allocation_capacity_and_payload_test_passed":true,"all_dispatch_classes_and_partial_blocks_test_passed":true,"new_random_index_groups":8192,"new_timings":0,"new_proofs":0,"proof_ledger":29953,"proof_ledger_sha256":hash(ledger),"adopted":false,"goal_achieved":false});fs::write(format!("{R}/review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Review PASS:{}source/library pins,3successful commands,2new loader tests/35field tests inherited; no timings",pins.len());}
